#!/usr/bin/env python3
"""
批量生成AI工具数据，使每个分类的数量与categories.json中的count匹配。
"""
import json
import random
from datetime import datetime, timedelta

# 读取现有数据
with open('data/tools.json', 'r', encoding='utf-8') as f:
    existing_tools = json.load(f)

with open('data/categories.json', 'r', encoding='utf-8') as f:
    categories = json.load(f)

# 统计现有各分类数量
cat_counts = {}
for t in existing_tools:
    cat = t.get('category', 'unknown')
    cat_counts[cat] = cat_counts.get(cat, 0) + 1

# 目标数量
targets = {c['slug']: c['count'] for c in categories if c['slug'] not in ['mcp', 'ai-prompt', 'ai-workflow', 'ai-news']}

# 各分类需要补充的数量
needed = {}
for cat, target in targets.items():
    current = cat_counts.get(cat, 0)
    needed[cat] = max(0, target - current)

print("各分类需要补充的数量:")
for cat, n in sorted(needed.items()):
    print(f"  {cat}: 现有{cat_counts.get(cat,0)}个, 目标{targets[cat]}个, 需补充{n}个")
print(f"总计需补充: {sum(needed.values())}条")

